                if (bitStream.WriteMask((mask & 0x01) != 0))
                {
    
    
                    var fieldValue = (data.rot.ToCoreQuaternion());
    

    
                    bitStream.WriteQuaternion(fieldValue, 32);
                }
    
                mask >>= 1;
                if (bitStream.WriteMask((mask & 0x01) != 0))
                {
    
    
                    var fieldValue = (data.scale.ToCoreVector3());
    

    
